(()=>{const out=[];for(const value of ['italic 150px serif','bold 24px/1.5 monospace','16px Arial','italic small-caps 700 condensed 20px/30px "Times New Roman", serif']){const e=document.createElement('div');e.style.font=value;document.body.appendChild(e);const c=getComputedStyle(e);out.push({input:value,cssText:e.style.cssText,entries:Array.from({length:e.style.length},(_,i)=>{const k=e.style.item(i);return [k,e.style.getPropertyValue(k)]}),computed:['font-size','font-style','font-family'].map(k=>[k,c.getPropertyValue(k)])});e.remove()}const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');document.body.appendChild(svg);const t=document.createElementNS(svg.namespaceURI,'text');svg.appendChild(t);t.textContent='abcd';t.style.font='italic 150px serif';const b=t.getBBox(),length=t.getComputedTextLength();t.style.cssText='font-style:italic;font-size:150px;font-family:serif';const c=t.getBBox();out.push({svgShorthandMatchesLonghands:['x','y','width','height'].every(k=>b[k]===c[k])&&length===t.getComputedTextLength()});svg.remove();return {rows:out}})()